def tables_in(sql):
    return sorted(t for t in TABLES if re.search(r"\b" + t + r"\b", sql))

with open(OUT, "w", encoding="utf-8") as f:
    for i, (d, q, sql, tags, om) in enumerate(ITEMS, 1):
        f.write(json.dumps({"id": f"chinook-{i:03d}", "question": q, "sql": sql, "difficulty": d,
                            "tags": tags, "tables": tables_in(sql), "order_matters": om,
                            "expected_row_count": None}, ensure_ascii=False) + "\n")
